import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        switch (n) {
            case 1:
                System.out.println("上数据");
                break;
            case 2:
                System.out.println("加一元素鱼汤");
                break;
            case 3:
                System.out.println("上清水");
                break;
            default:
                System.out.println("我们没这道菜");
        }
    }
}

